-    return (Array.isArray(tickets) ? tickets : []).map(function (t) {
+    var items = (Array.isArray(tickets) ? tickets : []).map(function (t) {
         return {
             key: t.key,
             labels: t.labels || [],
@@ -31,6 +31,21 @@ function query(rule, ctx) {
