            if (sRun.conclusion === 'success') {
                try {
                    github_remove_label({
                        workspace: effectiveRepoInfo.owner, repository: effectiveRepoInfo.repo,
                        number: ticket.prNumber, label: 'ai_validating'
                    });
                    github_add_labels({
                        workspace: effectiveRepoInfo.owner, repository: effectiveRepoInfo.repo,
                        number: ticket.prNumber, labels: ['ai_validated']
                    });
