    var obj = res;
    if (typeof res === 'string') {
        try { obj = JSON.parse(res); } catch (e2) { obj = null; }
    }
    if (obj && typeof obj === 'object') {
        return typeof obj.number === 'number' && !obj.message;
    }
    return false; // empty/unparseable body — unverifiable, do not anchor
}

